import RadioButton from "../../Elements/login/RadioButton";

interface DailyPrepItem {
    prep_list_id: number;
    name: string;
    description: string;
    quantity: number;
    unit: string;
    category: number;
    status: string;
  }

interface PrepListBreakdownProps {
    list: DailyPrepItem[];
    onCheck: () => void;
  }
  
  export default function PrepListBreakdown({ list, onCheck }: PrepListBreakdownProps) {
    // Group items by category
    const groupedItems = list.reduce((acc: { [key: string]: DailyPrepItem[] }, item) => {
      const categoryKey = `Category ${item.category}`; // Group items under "Category {category_id}"
      if (!acc[categoryKey]) {
        acc[categoryKey] = [];
      }
      acc[categoryKey].push(item);
      return acc;
    }, {});
  
    return (
      <div className="bg-white p-4 shadow rounded-md">
        <h2 className="text-xl font-bold mb-4">Prep List Breakdown</h2>
        <RadioButton 
            label="Verify?"
            onChange={onCheck}
            checked={false}
            size="medium"
        />
        {Object.entries(groupedItems).map(([category, items]) => (
          <div key={category} className="mb-6">
            <h3 className="text-lg font-semibold mb-2">{category}</h3>
            <ul className="list-disc pl-5 space-y-2">
              {items.map((item) => (
                <li key={item.prep_list_id}>
                  <div className="flex justify-between items-center">
                    <div>
                      <strong>{item.name}</strong> - {item.description}
                    </div>
                    <div>
                      {item.quantity} {item.unit}
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    );
  }